            long frozenVersion=n(M08FormalTest.read(101).get("version"));String frozen=Db.one("SELECT sources_json FROM m08_summary_revisions WHERE project_id=101 AND revision=?",frozenVersion).get("sources_json").toString();approveSummary();String firstWord=exportXml();check(firstWord.contains("8.00"),"Word uses actual M07 exact mean");check(!firstWord.contains("SYNTHETIC_PRIVATE"),"Word excludes raw answer marker");
