            M08FormalTest.rejects(401,()->TrainingSummariesIntegration.read(oldSession,101));var afterRevoke=M08FormalTest.read(101);eq("SURVEY_READ_REQUIRED",m(m(afterRevoke.get("sources")).get("feedback")).get("reason"));eq(null,m(afterRevoke.get("sources")).get("source_version"));eq(false,afterRevoke.get("source_changed"));eq(frozen,Db.one("SELECT sources_json FROM m08_summary_revisions WHERE project_id=101 AND revision=?",frozenVersion).get("sources_json"));
