    private static String cell(String ref,String value){return "<c r=\""+ref+"\" t=\"inlineStr\"><is><t>"+value.replace("&","&amp;").replace("<","&lt;")+"</t></is></c>";}
    private static byte[]xlsx(String marker,String score)throws Exception{String ns="http://schemas.openxmlformats.org/spreadsheetml/2006/main",rel="http://schemas.openxmlformats.org/officeDocument/2006/relationships";StringBuilder sheet=new StringBuilder("<worksheet xmlns=\"").append(ns).append("\"><sheetData><row r=\"1\">").append(cell("A1","record"));for(int i=0;i<10;i++)sheet.append(cell((char)('B'+i)+"1",SurveySummaryImportsResponses.QUESTION_LABELS.get(i)));sheet.append("</row><row r=\"2\">").append(cell("A2",marker));for(int i=0;i<10;i++)sheet.append(cell((char)('B'+i)+"2",score));sheet.append("</row></sheetData></worksheet>");Map<String,String>parts=new LinkedHashMap<>();parts.put("[Content_Types].xml","<Types xmlns=\"http://schemas.openxmlformats.org/package/2006/content-types\"><Default Extension=\"xml\" ContentType=\"application/xml\"/></Types>");parts.put("xl/workbook.xml","<workbook xmlns=\""+ns+"\" xmlns:r=\""+rel+"\"><sheets><sheet name=\""+SurveySummaryImportsResponses.SHEET_NAME+"\" sheetId=\"1\" r:id=\"one\"/></sheets></workbook>");parts.put("xl/_rels/workbook.xml.rels","<Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\"><Relationship Id=\"one\" Type=\""+rel+"/worksheet\" Target=\"worksheets/sheet1.xml\"/></Relationships>");parts.put("xl/worksheets/sheet1.xml",sheet.toString());ByteArrayOutputStream out=new ByteArrayOutputStream();try(ZipOutputStream zip=new ZipOutputStream(out)){for(var p:parts.entrySet()){ZipEntry e=new ZipEntry(p.getKey());e.setTime(0);zip.putNextEntry(e);zip.write(p.getValue().getBytes(StandardCharsets.UTF_8));zip.closeEntry();}}return out.toByteArray();}
